with x as (select * from json_to_recordset('[{"s":"abhi-meer","t":"Wild City #178: Abhi Meer (published 2019)","u":"https://soundcloud.com/thewildcity/wild-city-mix-178-abhi-meer"},{"s":"dreamstates","t":"Mixmag Asia Radio 102: dreamstates (published 2022)","u":"https://www.mixcloud.com/mixmagasia/mixmag-asia-radio-102-dreamstates-india/"},{"s":"dreamstates","t":"Zokhuma B2B Dreamstates | Mixmag Lab Goa","u":"https://www.youtube.com/watch?v=r-1GDbUJ8nM"},{"s":"jael","t":"Mixtape: JAEL (KALTBLUT Magazine) (published 2024)","u":"https://www.kaltblut-magazine.com/mixtape-jael/"},{"s":"kaleekarma","t":"Kaleekarma | Mixmag Lab Goa (published 2022)","u":"https://www.youtube.com/watch?v=N82rR5GsMUo"},{"s":"lush-lata","t":"Magnetic Fields 2024 | Lush Lata (Refuge Worldwide) (published 2025)","u":"https://refugeworldwide.com/radio/magnetic-fields-2024-lush-lata-09-feb-2025"},{"s":"suchi","t":"Ikke Sant with SUCHI - 11 December 2025 (Rinse FM) (published 2025)","u":"https://soundcloud.com/rinsefm/suchi111225"},{"s":"suchi","t":"SUCHI 21st May 2022 (NTS) (published 2022)","u":"https://www.nts.live/shows/guests/episodes/suchi-21st-may-2022"}]'::json) as x(s text,t text,u text) where exists (select 1 from public.artists a where a.slug=x.s)), ins as (insert into public.artist_tracklists (artist_slug,mix_title,url,tracks) select x.s,x.t,x.u,'[]'::jsonb from x on conflict (artist_slug,url) do nothing returning 1), fill as (update public.artists a set mix_url=f.u from (select distinct on (x.s) x.s,x.u from x order by x.s, (x.u ~ '(soundcloud\.com|youtube\.com|youtu\.be|mixcloud\.com)') desc) f where a.slug=f.s and a.mix_url is null returning 1) select (select count(*) from ins) ins, (select count(*) from fill) filled;